import copy


def merge_config(defaults, overrides):
    """Merge two config dicts.

    When both values for a key are dicts, they are merged recursively.
    For any other type (scalars, lists, None), the override value wins.
    The returned structure is deep-copied so mutations never affect inputs.
    """
    result = {}
    for key in set(defaults) | set(overrides):
        default_value = defaults.get(key)
        override_value = overrides.get(key)
        if isinstance(default_value, dict) and isinstance(
            override_value, dict
        ):
            result[key] = merge_config(default_value, override_value)
        else:
            result[key] = copy.deepcopy(
                override_value if key in overrides else default_value
            )
    return result

